      if (initialVersion > 0) requireQueueMessageScrub(database, now(), true);
      database.query("INSERT OR IGNORE INTO migrations(version, applied_at) VALUES (?, ?)").run(23, now());
      database.exec("PRAGMA user_version = 23");
